/** Push notifications: fake FCM HTTP v1 and APNs provider API (types, limits, reference tables). */

export type PushPreset = 'fcm' | 'apns';
export type PushPlatform = 'ios' | 'android' | 'web';
export type PushProvider = 'fcm' | 'apns';
export type UnknownTokens = 'accept' | 'reject';
export type NotificationStatus = 'delivered' | 'collapsed' | 'rejected' | 'dropped' | 'validated' | 'no_subscribers';

export interface FcmConfig {
  fcmProjectId: string;
  clientEmail: string;
  clientId: string;
  privateKeyId: string;
  /** RSA 2048, generated by stubyard (fake; only shown through the service-account download). */
  privateKeyPem: string | null;
  publicKeyPem: string;
  unknownTokens: UnknownTokens;
}

export interface ApnsConfig {
  teamId: string;
  keyId: string;
  bundleIds: string[];
  environment: 'sandbox' | 'production';
  /** P-256, generated by stubyard (downloadable AuthKey_<keyId>.p8). Null when only a public key was uploaded. */
  privateKeyPem: string | null;
  publicKeyPem: string;
  unknownTokens: UnknownTokens;
}

export interface PushInstance {
  id: string;
  projectId: string;
  slug: string;
  name: string;
  preset: PushPreset;
  config: FcmConfig | ApnsConfig;
  /** Strict: authentication problems are errors (lax: accepted with a warning). */
  strict: boolean;
  enabled: boolean;
  createdAt: string;
}

export interface PushDevice {
  id: string;
  projectId: string;
  testUserId: string | null;
  runId: string | null;
  instanceId: string | null;
  platform: PushPlatform;
  token: string;
  appId: string | null;
  name: string;
  state: 'active' | 'unregistered';
  unregisteredAt: string | null;
  topics: string[];
  badge: number | null;
  /** Created on the first push to an unknown token (unknownTokens 'accept'). */
  auto: boolean;
  lastPushAt: string | null;
  createdAt: string;
}

export interface PushNotification {
  id: string;
  projectId: string;
  instanceId: string | null;
  deviceId: string | null;
  testUserId: string | null;
  runId: string | null;
  logId: string | null;
  groupId: string | null;
  provider: PushProvider;
  targetKind: 'token' | 'topic' | 'condition';
  target: string;
  title: string | null;
  body: string | null;
  image: string | null;
  data: Record<string, unknown>;
  badge: number | null;
  sound: string | null;
  category: string | null;
  threadId: string | null;
  collapseKey: string | null;
  priority: string | null;
  pushType: string | null;
  silent: boolean;
  expiresAt: string | null;
  status: NotificationStatus;
  errorCode: string | null;
  providerMessageId: string | null;
  headers: Record<string, string>;
  raw: unknown;
  lint: PushLintFinding[];
  openedAt: string | null;
  createdAt: string;
}

export interface PushRule {
  id: string;
  projectId: string;
  runId: string | null;
  instanceId: string | null;
  match: { token?: string; user?: string; topic?: string };
  fault: string;
  remaining: number | null;
  hits: number;
  createdAt: string;
}

export interface PushLintFinding {
  check: string;
  severity: 'error' | 'warn' | 'info';
  message: string;
}

/** Size limits of the real services. */
export const LIMITS = {
  /** FCM: the message payload (notification + data) of a send. */
  fcmPayloadBytes: 4096,
  /** APNs: body of a notification request (5120 for VoIP). */
  apnsPayloadBytes: 4096,
  apnsVoipPayloadBytes: 5120,
  apnsCollapseIdBytes: 64,
  /** FCM condition: at most 5 topics. */
  fcmConditionTopics: 5,
  /** Instance ID batchAdd / batchRemove: at most 1000 tokens per call. */
  iidBatchTokens: 1000,
  /** Lint push.payload-near-limit above this many bytes. */
  nearLimitBytes: 3500,
  /** APNs provider tokens older than this are rejected (ExpiredProviderToken). */
  apnsTokenMaxAgeSec: 3600,
  /** A new APNs provider token for the same key more often than this → TooManyProviderTokenUpdates. */
  apnsTokenMinRefreshSec: 20 * 60,
  /** FCM OAuth access tokens live this long. */
  fcmAccessTokenSec: 3599,
  /** Fake OAuth tokens kept at once (oldest dropped first) and scopes stored per token: lax mode signs anything. */
  fcmTokenMaxActive: 1000,
  fcmTokenMaxScopes: 20,
  rawBytes: 16 * 1024,
} as const;

/** APNs apns-push-type values and the topic suffix each one expects (Apple: "Sending notification requests to APNs"). */
export const APNS_PUSH_TYPES: Record<string, string> = {
  alert: '',
  background: '',
  location: '.location-query',
  voip: '.voip',
  complication: '.complication',
  fileprovider: '.pushkit.fileprovider',
  mdm: '',
  liveactivity: '.push-type.liveactivity',
  pushtotalk: '.voip-ptt',
  widgets: '.push-type.widgets',
  controls: '.push-type.controls',
  accessory: '.push-type.accessory',
};

