/** FCM v1 error codes (FcmError.errorCode) with their HTTP status and google.rpc status. */
export const FCM_ERRORS: Record<string, { http: number; status: string; description: string }> = {
  UNSPECIFIED_ERROR: { http: 500, status: 'INTERNAL', description: 'No more information is available about this error.' },
  INVALID_ARGUMENT: { http: 400, status: 'INVALID_ARGUMENT', description: 'Request parameters were invalid (bad token format, non-string data value, several targets, payload too large…).' },
  UNREGISTERED: { http: 404, status: 'NOT_FOUND', description: 'The app instance was unregistered from FCM: the token is no longer valid; remove it.' },
  SENDER_ID_MISMATCH: { http: 403, status: 'PERMISSION_DENIED', description: 'The authenticated sender ID is different from the sender ID of the registration token.' },
  QUOTA_EXCEEDED: { http: 429, status: 'RESOURCE_EXHAUSTED', description: 'Sending limit exceeded for the message target; retry with exponential backoff.' },
  UNAVAILABLE: { http: 503, status: 'UNAVAILABLE', description: 'The server is overloaded; retry with exponential backoff.' },
  INTERNAL: { http: 500, status: 'INTERNAL', description: 'An unknown internal error occurred; retry with exponential backoff.' },
  THIRD_PARTY_AUTH_ERROR: { http: 401, status: 'UNAUTHENTICATED', description: 'The APNs certificate or web push auth key was invalid or missing.' },
};
